const profile = $json.profile;
const jobs = [
  { external_id: 'demo-001', source: 'example', title: 'Backend Engineer', company: 'Example Co', location: 'Singapore', work_mode: 'hybrid', url: 'https://example.com/jobs/demo-001', description: 'Python, FastAPI, PostgreSQL, Docker' },
  { external_id: 'demo-002', source: 'example', title: 'Platform Engineer', company: 'Example Labs', location: 'Remote', work_mode: 'remote', url: 'https://example.com/jobs/demo-002', description: 'Python, AWS, Docker, Kubernetes' }
];
return jobs.map(job => ({ json: { profile, job } }));

const profile = $json.profile;
const jobText = `${$json.job.title} ${$json.job.description}`.toLowerCase();
const matched = profile.skills.filter(skill => jobText.includes(skill.toLowerCase()));
const score = Math.min(100, Math.round((matched.length / Math.max(profile.skills.length, 1)) * 70 + (profile.target_roles.some(role => $json.job.title.toLowerCase().includes(role.toLowerCase())) ? 20 : 0) + ($json.job.work_mode && profile.work_modes.includes($json.job.work_mode) ? 10 : 0)));
return [{ json: { ...$json, match: { score, matched_skills: matched, missing_skills: profile.skills.filter(skill => !matched.includes(skill)), confidence: matched.length ? 'medium' : 'low' } } }];

const { profile, job, match } = $json;
const coverLetter = `Draft cover letter for ${job.title} at ${job.company}.

I am interested in this role because my experience aligns with: ${match.matched_skills.join(', ') || 'the role requirements'}.

Please verify every claim before submission.`;
return [{ json: { ...$json, application_draft: { cover_letter: coverLetter, resume_version: 'current', facts_used: match.matched_skills, approval_status: 'PENDING_REVIEW' }, guardrail: { require_human_approval: profile.consent.require_approval_before_submit === true, auto_submit: false } } }];
